arguments.argument:
if obj_draw.click_number>-1
{
file_delete(global.fodre+string(obj_draw.click_number)+".dlrc")
//파일삭제

for(i=obj_draw.click_number+1; i!=global.tri_max_number+1; i+=1)
{
file_rename(global.fodre+string(i)+".dlrc", global.fodre+string(i-1)+".dlrc")
}
//이름변경

sk_res()
//지형불르기

if obj_draw.click_number>=global.tri_max_number{obj_draw.click_number-=1}

obj_draw.key_start_key-=1

if obj_draw.key_start_key>global.tri_max_number-obj_draw.key_max
{
obj_draw.key_start_key=global.tri_max_number-obj_draw.key_max
}
if obj_draw.key_start_key<0
{
obj_draw.key_start_key=0
}
//최대,최소값 넘으면 조정

obj_draw.alarm[0]=10
//얼마동안 드로우못하게
}
